import{d as g,C as t,o as d,c as h,a3 as e,E as i,j as a,a as p}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"正易心法·第二章","description":"《正易心法》第二章——六画之设非是曲意：以「阴阳运动」对应十二消息卦、以「血气流行」对应脏腑配数，论证六爻重卦是天道与人体的同一节律。","frontmatter":{"title":"正易心法·第二章","description":"《正易心法》第二章——六画之设非是曲意：以「阴阳运动」对应十二消息卦、以「血气流行」对应脏腑配数，论证六爻重卦是天道与人体的同一节律。","category":"guide","aliases":["正易心法第二章","六画之设","阴阳运动血气流行"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-02.md","filePath":"yijing/zheng-yi-xin-fa/chapter-02.md","lastUpdated":1790647676000}'),u={name:"yijing/zheng-yi-xin-fa/chapter-02.md"},x=g({...u,setup(c){const s=[{id:"z2-01",label:"一、非是曲意",showLabel:!0,sentences:[[{text:"六画",glossary:"liuhua"},"之设，非是",{text:"曲意",glossary:"quyi"},"。"]],note:["六爻重卦的设立，并不是出于人为的刻意安排。（「曲意」即委曲造作之意——不是伏羲「设计」了六十四卦，而是天地人三才的节律本来如此，他只是把它画了出来。）"]},{id:"z2-02",label:"二、阴阳运动",showLabel:!0,sentences:[[{text:"阴阳运动",glossary:"yinyang"},"，若一阳为",{text:"复",glossary:"fu"},"，至六阳为乾，一阴为",{text:"姤",glossary:"gou"},"，至六阴为坤是也。"]],note:["所谓阴阳运动：一阳生为复卦，渐长到六阳为乾卦；一阴生为姤卦，渐长到六阴为坤卦。这就是阴阳的消长——即十二消息卦的次第。"]},{id:"z2-03",label:"三、血气流行",showLabel:!0,sentences:[[{text:"血气流行",glossary:"xueqi"},"，若一六为肾，二为肺，三为脾，四为肝，五为心，"]],note:["所谓血气流行：一与六对应肾，二对应肺，三对应脾，四对应肝，五对应心。这不是随便的配法——「天一生水，地六成之」出自《河图》，水在五行属肾，所以「一六为肾」正是生成数的直接应用。"]},{id:"z2-04",label:"四、始生屯",showLabel:!0,sentences:[["始生",{text:"屯",glossary:"zhun"},"。屯而为",{text:"蒙",glossary:"meng"},"，养蒙为",{text:"需",glossary:"xu"},"之类是也。"]],note:["从这里开始生出屯卦；屯卦发展为蒙卦，养蒙则为需卦，如此之类。这是用生理的节律解释卦序：肾气初动（一六），生命开始，对应屯；接着脾胃（三）运化养育，对应蒙；再往后是饮食滋养，对应需。"]},{id:"z2-05",label:"五、顺此理而已",showLabel:!0,sentences:[["卦画凡以此",{text:"顺此理",glossary:"shunCili"},"而已。"]],note:["卦画的设立，不过是顺应这个道理罢了。（天道与人体的节律本是一理，卦画只是把它如实地画出来。）"]}],o=[{id:"liuhua",term:"六画",pinyin:"liù huà",meaning:"重卦的六爻，即六十四卦每卦的六条爻线。"},{id:"quyi",term:"曲意",pinyin:"qū yì",meaning:"委曲、勉强之意，此处指人为造作、刻意安排。"},{id:"yinyang",term:"阴阳运动",pinyin:"yīn yáng yùn dòng",meaning:"阴阳二气的消长变化，对应十二消息卦的卦序。"},{id:"xueqi",term:"血气流行",pinyin:"xuè qì liú xíng",meaning:"气血在人体中的运行，对应脏腑与卦数的配属。"},{id:"fu",term:"复",pinyin:"fù",meaning:"复卦（一阳在下），十二消息卦之首，冬至一阳生。"},{id:"gou",term:"姤",pinyin:"gòu",meaning:"姤卦（一阴在下），十二消息卦之一，夏至一阴生。"},{id:"zhun",term:"屯",pinyin:"zhūn",meaning:"屯卦，草木初生之象，六十四卦第三卦。"},{id:"meng",term:"蒙",pinyin:"méng",meaning:"蒙卦，童蒙待养之象，六十四卦第四卦。"},{id:"xu",term:"需",pinyin:"xū",meaning:"需卦，等待、饮食之象，六十四卦第五卦。"},{id:"shunCili",term:"顺此理",pinyin:"shùn cǐ lǐ",meaning:"顺应这个道理。强调卦画是自然之理，非人为设计。"}];return(m,n)=>{const r=t("DaoTextReading"),l=t("DaoKeywordCards");return d(),h("div",null,[n[0]||(n[0]=e("",17)),i(r,{colophon:"非是曲意 · 阴阳运动 · 血气流行 · 卦序自然",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二章原文",sections:s,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本，不作统一。原文「一六为肾，二为肺，三为脾，四为肝，五为心」与《黄帝内经》五脏配五行略有出入，是麻衣自己的配法，详见解读层。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(l,{items:[{term:"曲意",pinyin:["qū","yì"],meaning:"委曲、勉强之意，此处指人为造作、刻意安排。"},{term:"阴阳运动",pinyin:["yīn","yáng"],meaning:"阴阳二气的消长变化，对应十二消息卦的卦序。"},{term:"血气流行",pinyin:["xuè","qì"],meaning:"气血在人体中的运行，对应脏腑与卦数的配属。"},{term:"十二消息卦",pinyin:["shí","èr"],meaning:"复、临、泰、大壮、夬、乾（阳长）；姤、遁、否、观、剥、坤（阴长），以十二卦配十二月。"},{term:"河图生成数",pinyin:["hé","tú"],meaning:"「天一生水，地六成之」等生数与成数相配之说。水属肾，故「一六为肾」。"}]}),n[3]||(n[3]=e("",24))])}}});export{b as __pageData,x as default};
